function bizAdornment(b,n){const id=b.id;const sign={kiosk:'OPEN',cafe:'CAFÉ',delivery:'EXPRESS',studio:'STUDIO',taxi:'TAXIS',factory:'AUTO',bank:'FINANCE',space:'ORBIT'}[id];if(id==='lemon')return n>1?`<path d="M157 124 L164 119 L174 121 L167 126Z" fill="#f6d9a9"/><path d="M164 119 v-14" stroke="#eee7c1" stroke-width="2"/>`:'';let s=`<path d="M122 145 L189 113 L251 145 L190 173Z" fill="#1e3946" opacity=".8"/><text x="190" y="150" fill="#f5e3bb" text-anchor="middle" font-size="11" font-weight="900">${sign}</text>`;if(id==='factory'||id==='space')s+=`<path d="M106 104 L118 96 L118 53 L106 58Z" fill="#b4c9c7"/><path d="M118 53 L129 58 L129 103 L118 96Z" fill="#6e8c9b"/><path d="M234 87 L244 81 L244 43 L233 49Z" fill="#b0c2c6"/><circle cx="113" cy="48" r="9" fill="#d1e5dc" opacity=".46"/><circle cx="121" cy="35" r="12" fill="#d1e5dc" opacity=".25"/>`;if(id==='bank')s+=`<path d="M107 125 L189 84 L272 122" fill="none" stroke="#e9c88e" stroke-width="9"/><path d="M118 132 V175 M155 111 V188 M221 111 V187 M260 134 V172" stroke="#e9ddc8" stroke-width="6"/>`;if(id==='cafe')s+=`<path d="M277 166 C260 146 281 138 286 149 C297 137 302 153 287 164Z" fill="#f5e4b5"/>`;if(id==='delivery'||id==='taxi')s+=`<path d="M287 190 L326 173 L344 183 L307 203Z" fill="${b.color}"/><path d="M307 203 L344 183 V195 L308 216Z" fill="#334754"/><circle cx="310" cy="211" r="5" fill="#27343e"/><circle cx="331" cy="202" r="5" fill="#27343e"/>`;if(id==='studio')s+=`<path d="M304 93 L330 82 L329 102 L304 113Z" fill="#2c3648"/><circle cx="320" cy="96" r="5" fill="#8cb5d5"/><path d="M314 110 L316 125" stroke="#323c4b" stroke-width="4"/>`;return s}
function bizSVG(b,level=1){if(!b)b=BIZ[0];const n=Math.min(4,Math.max(1,level));const hue=b.color;const premium=n>=3;const isLemon=b.id==='lemon';return svgBase(`<rect width="380" height="250" fill="#4f7680"/><path d="M0 165 L187 78 L380 164 L200 250Z" fill="#718d8b"/><path d="M0 204 L190 116 L380 195 L262 250 L84 250Z" fill="#9ba49a" opacity=".62"/><ellipse cx="188" cy="213" rx="124" ry="26" fill="#14313b" opacity=".5" filter="url(#shadow)"/><path d="M83 143 L191 96 L294 148 L186 198Z" fill="#627c7e"/><path d="M83 143 L83 179 L186 233 L186 198Z" fill="#476375"/><path d="M186 198 L294 148 L294 181 L186 233Z" fill="#334c5a"/>${n===1?`<path d="M118 119 L192 88 L265 121 L190 156Z" fill="#b6a08c"/><path d="M118 119 L118 154 L190 191 L190 156Z" fill="url(#wood)"/><path d="M190 156 L265 121 L265 155 L190 191Z" fill="#8f634d"/><path d="M143 123 L192 102 L239 122 L190 145Z" fill="#d7c6a7"/><rect x="169" y="124" width="16" height="12" rx="3" fill="#ffe2a5"/>`:n===2?`<path d="M99 122 L192 80 L290 125 L191 167Z" fill="${hue}"/><path d="M99 122 L99 161 L191 207 L191 167Z" fill="#ba8e68"/><path d="M191 167 L290 125 L290 165 L191 207Z" fill="#8e6a54"/><path d="M105 106 L192 69 L281 110 L192 150Z" fill="#f0dfc0"/><path d="M105 110 L113 130 L192 167 L192 149Z" fill="#db8e68"/><path d="M192 149 L281 110 L275 130 L192 167Z" fill="#f6c98a"/><path d="M154 153 L220 121 L236 128 L170 160Z" fill="#f4e6c7"/>`:`<path d="M78 114 L188 65 L304 116 L190 170Z" fill="#c9d8d3"/><path d="M78 114 L78 164 L190 221 L190 170Z" fill="${n===4?'#c1ada0':'#dfd7c8'}"/><path d="M190 170 L304 116 L304 167 L190 221Z" fill="${n===4?'#9a9f98':'#9fb4b1'}"/><path d="M102 118 L189 79 L277 118 L190 160Z" fill="${n===4?'#acb8ad':'#738f96'}"/><path d="M109 119 L189 84 L266 117 L190 155Z" fill="url(#glass)"/><path d="M135 132 L135 190 M245 131 L245 194" stroke="#e9e8de" stroke-width="4"/><path d="M191 171 V218" stroke="#dde5dc" stroke-width="4"/><path d="M76 110 L187 58 L307 113 L296 119 L188 70 L85 119Z" fill="${n===4?'#d9b986':'#edf0df'}" stroke="#f2e3bc" stroke-width="2"/>${n===4?`<path d="M112 110 L190 76 L265 110 L189 147Z" fill="#e9d6b1"/><path d="M115 110 L190 78 L264 110" fill="none" stroke="#f9e6b9" stroke-width="3"/>`:''}`}<path d="M145 ${n===1?157:164} L190 ${n===1?178:187} L236 ${n===1?156:166} L190 ${n===1?137:144}Z" fill="#e8cc9e" opacity=".92"/><text x="190" y="${n===1?166:177}" text-anchor="middle" font-size="10" font-family="system-ui" font-weight="900" fill="#4b4337">${isLemon?'LEMON':b.name.toUpperCase().slice(0,12)}</text>${isLemon?`<g transform="translate(207 128)"><ellipse cx="0" cy="0" rx="13" ry="8" fill="#f1d15a" stroke="#eee7ad" stroke-width="2"/><path d="M-3 -4 Q0 -12 6 -8" fill="none" stroke="#5a9c5f" stroke-width="3"/></g>`:`<g transform="translate(209 123)"><circle r="14" fill="${hue}" stroke="#f8e4c3" stroke-width="2"/><text text-anchor="middle" y="5" font-size="15">${b.icon}</text></g>`}${n===4?`<circle cx="114" cy="123" r="3" fill="#fff4bf"/><circle cx="267" cy="127" r="3" fill="#fff4bf"/><path d="M190 150 L190 171" stroke="#ffe8b2" stroke-width="3"/>`:''}${bizAdornment(b,n)}${avatarFigure(100,201,.5)}`)}
function carSVG(tier=0,color='#f1a07c'){return svgBase(`<rect width="380" height="250" fill="#506c76"/><path d="M0 160 L200 70 L380 158 L175 250Z" fill="#99a7a1"/><path d="M0 213 L186 120 L380 214 L301 250 L76 250Z" fill="#556e78"/><ellipse cx="190" cy="184" rx="122" ry="34" fill="#14303b" opacity=".5" filter="url(#shadow)"/><path d="M88 150 L158 119 L254 133 L297 164 L263 187 L157 195 L82 169Z" fill="${color}" stroke="#e9f4f0" stroke-width="2"/><path d="M158 119 L185 98 L244 113 L254 133 L211 148 L129 142Z" fill="#344e64" stroke="#e3eef0" stroke-width="2"/><path d="M185 102 L175 121 L212 137 L237 115Z" fill="#95cbd5"/><path d="M141 125 L169 111 L158 124 L131 137Z" fill="#a7dce7"/><path d="M82 168 L156 195 L263 187 L296 165" stroke="#526a75" stroke-width="3" fill="none"/><ellipse cx="130" cy="180" rx="15" ry="17" fill="#192633" stroke="#bbcbd1" stroke-width="4"/><ellipse cx="254" cy="178" rx="15" ry="17" fill="#192633" stroke="#bbcbd1" stroke-width="4"/><ellipse cx="130" cy="180" rx="6" ry="8" fill="#889daa"/><ellipse cx="254" cy="178" rx="6" ry="8" fill="#889daa"/><path d="M89 145 L111 151 L111 158 L85 153Z M272 151 L289 160 L284 165 L270 158Z" fill="#f7e8ba"/><path d="M181 152 L220 158" fill="none" stroke="#f6e5c8" stroke-width="2"/>${tier>=3?`<path d="M135 126 L173 110 L245 126" stroke="#ffe7a4" stroke-width="4" fill="none"/>`:''}`)}
function avatarSVG(){return svgEnvironment(`<path d="M70 237 243 159 423 242 242 308Z" fill="#617d83"/><ellipse cx="240" cy="266" rx="55" ry="15" fill="#132633" opacity=".5"/><circle cx="244" cy="100" r="61" fill="#63899c" opacity=".24"/>${avatarFigure(238,268,2.05)}<text x="240" y="33" text-anchor="middle" font-size="16" font-weight="800" fill="#f3e1c4">PERSONNAGE PERSONNALISABLE</text>`) }
