function islandSVG(){return svgBase(`<rect width="380" height="250" fill="#5ba0ae"/><path d="M0 175 Q80 155 135 175 Q230 138 380 176 V250 H0Z" fill="#65b1b7"/><path d="M44 168 L181 94 L338 162 L191 236Z" fill="#d5c68f"/><path d="M66 156 L181 106 L317 162 L190 224Z" fill="#75aa81"/><path d="M165 130 L165 84" stroke="#69523d" stroke-width="13"/><path d="M165 80 Q135 55 115 85 Q154 88 165 80 Q189 51 223 77 Q187 85 165 80 Q171 39 156 42 Q150 60 165 80" fill="#447c55"/><path d="M242 163 L257 155 L272 163 L256 170Z" fill="#a7a6a1"/><path d="M242 163 L242 181 L256 188 L256 170Z" fill="#777e7f"/><path d="M256 170 L272 163 L272 180 L256 188Z" fill="#56656c"/>${avatarFigure(183,191,1)}`)}
function premiumSelectedCar(){const owned=Array.isArray(S.cars)?S.cars:[];if(!owned.length)return -1;return owned.includes(S.featuredCar)?S.featuredCar:owned[owned.length-1]}
function premiumCarArt(i){if(i<0)return '<div class="premium-empty-garage"><span>◇</span><strong>Ton futur véhicule</strong><small>Débloque un véhicule dans le garage</small></div>';return `<img alt="${e(CARS[i].name)}" loading="lazy" src="art/car_${i}.webp">`}
function premiumBiz(){const owned=BIZ.filter(b=>S.biz[b.id]);if(!owned.length)return `<div class="premium-empty">Ton empire commence aujourd’hui. Fonde ton premier commerce !</div><button data-page="business" class="premium-primary">＋ Fonder une entreprise</button>`;return owned.slice(0,3).map(b=>`<button class="premium-listline" data-page="business"><img src="art/${artBiz(b,S.biz[b.id].level)}.webp" alt=""><span><b>${e(b.name)}</b><small>Niv. ${S.biz[b.id].level} · ${fmt(b.income*Math.pow(1.63,S.biz[b.id].level-1)*S.biz[b.id].count)}/s</small></span><span>›</span></button>`).join('')}
function premiumCard(title,icon,target,content,extra=''){return `<section class="premium-card ${extra}"><button class="premium-card-head" data-page="${target}"><strong><span>${icon}</span> ${title}</strong><span>›</span></button>${content}</section>`}
function homePage(){const h=HOMES[S.home]||HOMES[0],owned=Object.keys(S.biz).length,ci=premiumSelectedCar(),pet=LOOT.find(x=>x.id===safeEquip().pet),today=new Date().toLocaleDateString('fr-CA');let properties=[S.home,Math.min(29,S.home+1),Math.min(29,S.home+2)].filter((v,i,a)=>a.indexOf(v)===i);if(properties.length<3)properties=[0,13,29];const games=[['🏙','Empire Rush','art/arcade_empire.webp'],['📈','Crypto Trader','art/arcade_crypto.webp'],['🏎','Rallye Prestige','art/arcade_rally.webp'],['📚','Quiz Business','art/arcade_quiz.webp'],['♠','Casino VIP','art/arcade_casino.webp'],['🏰','Mission Patrimoine','art/arcade_heritage.webp']];return `<div class="premium-dashboard">
 <section class="premium-hero"><div class="premium-hero-back" style="background-image:linear-gradient(0deg,#07111d77,#07111d05 60%),url('art/${artHome(S.home)}.webp')"></div>
 <div class="premium-hero-top"><span class="premium-overline">✦ TON UNIVERS PERSONNEL</span><div class="premium-level">Niveau ${1+Math.floor(Math.log10(S.total/100+1))} <span>✦</span></div></div>
 <div class="premium-hero-actor">${avatarImg()}</div>${pet?`<div class="premium-pet" title="${e(pet.name)}">${pet.emoji}</div>`:''}
 <div class="premium-residence"><small>⌂ MA RÉSIDENCE</small><b>${e(h.name)}</b><small>${h.area.toLocaleString('fr-FR')} m²</small><button data-page="life">Voir ma maison ↗</button></div>
 <div class="premium-car-display"><button class="premium-garage-label" data-page="garage">⌁ GARAGE · ${ci<0?'À débloquer':e(CARS[ci].name)} ›</button><div class="premium-car-window">${premiumCarArt(ci)}</div><div class="premium-car-actions">${ci<0?'<button data-page="garage">Voir les véhicules</button>':`<button data-action="premium-prev-car">‹</button><span>${e(CARS[ci].name)}</span><button data-action="premium-next-car">›</button>`}</div></div>
 </section>
 <div class="premium-quick"><button data-page="earn"><span>✦</span>Gagner</button><button data-page="business"><span>▥</span>Business</button><button data-page="homes"><span>⌂</span>Immobilier</button><button data-page="garage"><span>▱</span>Véhicules</button><button data-page="games"><span>◈</span>Jeux</button><button data-page="gacha"><span>◇</span>Gacha</button><button data-page="shop"><span>♙</span>Boutique</button></div>
 <div class="premium-kpis"><div><small>PORTEFEUILLE</small><b>${fmt(S.cash)}</b></div><div><small>REVENUS AUTOMATIQUES</small><b class="premium-positive">+${fmt(income())}/s</b></div><div><small>MON EMPIRE</small><b>${owned} entreprise${owned>1?'s':''}</b></div></div>
 <div class="premium-grid">
 ${premiumCard('Cliquer et progresser','✦','earn',`<button data-page="earn" class="premium-clicker"><img src="art/${jobArt(S.job,S.clickLvl)}.webp" alt="${e(JOBS[S.job].name)}"><span><strong>${e(JOBS[S.job].name)}</strong><small>Niv. ${S.clickLvl} · +${fmt(JOBS[S.job].gain*S.clickLvl*titleMult())}/clic</small><em>Jouer et gagner ›</em></span></button>`,'premium-clicker-card')}
 ${premiumCard('Mes entreprises','▥','business',premiumBiz(),'premium-business-card')}
 ${premiumCard('Immobilier · 30 propriétés','⌂','homes',`<div class="premium-property-grid">${properties.map(i=>`<button data-page="homes" class="premium-property"><img src="art/home_${i}.webp" alt="${e(HOMES[i].name)}"><b>${e(HOMES[i].name)}</b><small>${fmt(HOMES[i].price)}</small></button>`).join('')}</div>`,'premium-estate-card')}
 ${premiumCard('Mon garage','▱','garage',`<button data-page="garage" class="premium-feature-car">${premiumCarArt(ci)}<span>${ci<0?'Découvre le catalogue':e(CARS[ci].name)} ›</span></button>`,'premium-car-card')}
 ${premiumCard('Personnalisation','♙','life',`<button data-page="life" class="premium-character-card">${avatarImg()}<span><b>${e(S.avatarName||'Mon personnage')}</b><small>Tenues · Coiffure · Équipements</small><em>Personnaliser →</em></span></button>`,'premium-avatar-card')}
 ${premiumCard('Les six univers de jeu','◈','games',`<div class="premium-games">${games.map(g=>`<button data-page="games" class="premium-game"><img src="${g[2]}" alt=""><span>${g[0]} ${g[1]}</span></button>`).join('')}</div>`,'premium-games-card')}
 ${premiumCard('Gacha & collection','◇','gacha',`<button class="premium-gacha" data-page="gacha"><span class="premium-chest">✧</span><span><b>Tes récompenses t’attendent</b><small>Vêtements, compagnons, titres et décorations</small><em>Ouvrir la collection ›</em></span></button>`,'premium-gacha-card')}
 <section class="premium-card premium-daily"><h3>✦ Bonus du jour</h3><p>Un bonus facultatif, sans série obligatoire.</p>${button(S.dailyClaim===today?'Déjà récupéré':'Récupérer 25 €','daily','premium-primary',S.dailyClaim===today)}</section>
 </div></div>`}
function earnPage(){const j=JOBS[S.job],next=JOBS[S.job+1],upCost=Math.round(18*Math.pow(1.68,S.clickLvl-1)*Math.pow(2.2,S.job)),per=j.gain*S.clickLvl;return `<div class="eyebrow">TRAVAIL & PREMIERS GAINS</div><h1 class="top-title">Chaque euro compte.</h1><p class="lead">Transforme tes premières ventes en nouvelles opportunités. Tape, améliore et choisis ton prochain métier.</p><div class="wallet"><div class="eyebrow" style="color:#b5e7ca">TON COMPTE</div><div class="amount">${fmt(S.cash)}</div><div class="row"><span class="small">${j.icon} ${j.name} · Niveau ${S.clickLvl}</span>${pill('+'+fmt(per)+' / clic','gold')}</div></div><div class="sect"><h2>Ton activité</h2><span class="label">Tape pour travailler</span></div><div class="tap-stage" id="tap-stage" data-action="tap">${`<img class="clicker-art" src="art/${jobArt(S.job,S.clickLvl)}.webp" alt="${e(j.name)}"><span class="clicker-level">${e(j.name)} · Niveau ${S.clickLvl}</span>`}<div class="tap-tip">TOUCHE POUR GAGNER · +${fmt(per)}</div></div><div class="panel" style="margin-top:14px"><div class="row"><div><h3>Améliorer ton activité</h3><div class="dim small">+${fmt(j.gain)} par clic · Niveau ${S.clickLvl+1}</div></div>${button(fmt(upCost),'click-up','btn sm',S.cash<upCost)}</div></div><div class="sect"><h2>Changer de métier</h2></div><div class="panel"><div class="row" style="gap:13px"><div class="circle-icon">${j.icon}</div><div style="flex:1"><strong>${j.name}</strong><div class="dim small">${j.desc}</div></div>${pill('Actuel')}</div>${next?`<div class="divider"></div><div class="row"><div><div class="dim small">Prochain métier</div><strong>${next.icon} ${next.name}</strong><div class="dim small">Rendement de base : ${fmt(next.gain)} / clic</div></div>${button('Débloquer · '+fmt(next.price),'unlock-job','btn sm',S.cash<next.price)}</div>`:`<div class="divider"></div><p class="dim small">Tu as atteint le dernier métier disponible pour cette version.</p>`}</div><p class="dim small">Les entreprises indépendantes produisent des revenus passifs même lorsque tu n'appuies plus sur le cliqueur.</p>`}
function businessPage(){const ids=Object.keys(S.biz);return `<div class="eyebrow">TON EMPIRE ÉCONOMIQUE</div><h1 class="top-title">Mes entreprises</h1><p class="lead">Fonde tes entreprises, agrandis-les et admire les bâtiments évoluer. Aucun impôt dans cette version.</p><div class="grid2" style="margin-bottom:14px">${boxstat('Revenus / seconde',fmt(income()))}${boxstat('Sociétés possédées',ids.reduce((n,k)=>n+S.biz[k].count,0))}</div><button class="btn wide" data-action="open-catalog" style="padding:20px;font-size:15px">＋ Fonder une entreprise</button><div class="sect"><h2>Mon portefeuille</h2><span class="label">${ids.length} types</span></div>${ids.length?ids.map(id=>{const b=BIZ.find(x=>x.id===id),ob=S.biz[id];return `<div class="business-row" data-action="biz-detail" data-id="${id}">${scene('business',{mini:true,biz:b,level:ob.level})}<div style="flex:1;min-width:0"><h3>${b.name}</h3><div class="dim tiny">Niveau ${ob.level} · ${ob.count} établissement${ob.count>1?'s':''}</div><div style="font-size:12px;color:var(--mint);margin-top:7px;font-weight:800">+${fmt(b.income*Math.pow(1.63,ob.level-1)*ob.count)}/s</div></div><div class="brow-right">›</div></div>`}).join(''):`<div class="empty"><div class="symbol">▥</div><strong>Ton empire commence ici</strong>Tu ne possèdes encore aucune entreprise.<p>Appuie sur « Fonder une entreprise » pour ouvrir le catalogue.</p></div>`}`}
function gamesPage(){return Arcade.catalog()}
function lifePage(){const home=HOMES[S.home];return `<div class="eyebrow">PERSONNAGE · LOGEMENT · COLLECTION</div><h1 class="top-title">Ma vie</h1><p class="lead">Une vraie tenue, une vraie maison, une collection vivante : compose ton univers à ton rythme.</p><div class="panel flush">${scene('room',{kind:S.home,label:home.name+' · '+home.area+' m²'})}<div class="hero-caption"><div class="row"><div><h2>${home.name}</h2><span class="dim small">Surface : ${home.area} m²</span></div>${button('Immobilier','homes','btn alt sm')} ${button('Boutique','go-shop','btn alt sm')}</div></div></div><div class="sect"><h2>Mon personnage</h2><span class="label">Personnalise ton style</span></div><div class="panel"><div class="grid2"><div>${scene('avatar',{tall:true})}</div><div class="col" style="justify-content:center">${[['Coiffure','hair',['Classique','Texturé','Ébouriffé','Casquette']],['Couleur','hairColor',['Noir','Châtain','Blond','Platine','Bleu']],['Vêtements','outfit',['Sweat bleu','Blouson orange','Sport','Violet','Beige']],['Peau','skin',['Clair','Doré','Brun','Foncé']]].map(v=>`<label><span class="form-label">${v[0]}</span><select class="select" data-avatar="${v[1]}">${v[2].map((x,i)=>`<option value="${i}" ${S.avatar[v[1]]===i?'selected':''}>${x}</option>`).join('')}</select></label>`).join('')}</div></div><div class="dim tiny" style="margin-top:9px">Les personnalisations sont enregistrées automatiquement.</div></div><div class="sect"><h2>Garage</h2>${button('Voir les véhicules','garage','btn alt sm')}</div><div class="panel">${S.cars.length?scene('vehicle',{tier:Math.max(...S.cars),color:S.carColor,label:CARS[premiumSelectedCar()].name}):`<div class="empty"><div class="symbol">🚲</div><strong>Ton garage est vide</strong>Ton premier véhicule n'attend que toi.</div>`}</div><div class="sect"><h2>Objets rares</h2>${button('Ouvrir le gacha','go-gacha','btn alt sm')}</div><div class="panel"><div class="row"><div><strong>${S.loot.length} objet(s)</strong><div class="dim small">Collection, petits compagnons et easter eggs</div></div><span style="font-size:34px">🎁</span></div></div>`}
function shopPage(){const outfits=[['Veste campus',450,3],['Sweat premium',2500,0],['Tenue sport',8000,7],['Blouson cuir',30000,6],['Tenue créateur',160000,9],['Costume prestige',750000,11]];return `<div class="eyebrow">BOUTIQUE · STYLE PERSONNEL</div><h1 class="top-title">Mon dressing</h1><p class="lead">Achète des tenues originales et porte-les sur ton avatar. Cette boutique est fictive et indépendante des marques réelles.</p><div class="grid2">${outfits.map((v,i)=>`<div class="tile"><img class="shop-avatar" src="art/avatar_${v[2]}.webp"><strong>${v[0]}</strong><small>${fmt(v[1])}</small>${button((S.shop||[]).includes(i)?'Porter':'Acheter','shop-'+i,'btn sm',!(S.shop||[]).includes(i)&&S.cash<v[1])}</div>`).join('')}</div></div>`}
function morePage(){return `<div class="eyebrow">TON ESPACE</div><h1 class="top-title">Plus</h1><div class="grid2"><button class="tile" data-page="gacha" style="color:white;text-align:left"><span style="font-size:27px">🎁</span><strong>Gacha</strong><span class="dim small">Récompenses et raretés</span></button><button class="tile" data-page="markets" style="color:white;text-align:left"><span style="font-size:27px">📈</span><strong>Marchés</strong><span class="dim small">Version économique future</span></button></div><div class="sect"><h2>Sauvegarde</h2></div><div class="panel"><p class="dim small">Ta partie est enregistrée automatiquement sur cet appareil. Exporte-la pour la conserver si tu changes de navigateur.</p><div class="grid2">${button('↓ Exporter','export','btn alt')}${button('↑ Importer','import','btn ghost')}${button('Nouvelle partie','reset','btn ghost')}${button('Mode démonstration','demo','btn alt')}</div><input id="import-file" type="file" accept="application/json,.json" style="display:none"/><div class="divider"></div><strong class="small">Statistiques</strong><div class="grid2" style="margin-top:9px">${boxstat('Gains cumulés',fmt(S.total))}${boxstat('Nombre de clics',num(S.taps))}</div></div><div class="panel"><h3>À venir</h3><p class="dim small">Cryptomonnaies liées aux cours réels, marchés boursiers, davantage de décorations, compagnons visibles et sauvegarde cloud. Ces fonctions ne sont pas simulées comme déjà disponibles.</p></div>`}
function gachaPage(){const cost=120,owned=LOOT.filter(x=>S.loot.includes(x.id)),eq=safeEquip();return `<div class="eyebrow">TRÉSORS · COLLECTION</div><h1 class="top-title">Gacha des légendes.</h1><p class="lead">Équipe tes tenues, invoque un compagnon visible près de ta maison et expose tes objets. Tes armes débloquées enrichissent ta collection. Tirages 100% en monnaie fictive.</p><div class="panel center"><div style="font-size:68px;filter:drop-shadow(0 0 16px #e8b96b)">✧ 🎁 ✧</div><h2>Invocation</h2><p class="dim small">Commun 48% · Rare 30% · Épique 17% · Légendaire 4,8% · Administrateur 0,2%</p>${button('Invoquer · '+fmt(cost),'gacha-roll','btn wide',S.cash<cost)}<p class="dim tiny">Titres ordinaires cumulés : multiplicateur maximum ×1,5. Le titre Administrateur ×3 est extrêmement rare et doit être équipé.</p></div><div class="grid2">${boxstat('Collection',owned.length+' / '+LOOT.length)}${boxstat('Bonus économie','×'+titleMult().toFixed(3))}</div><div class="sect"><h2>Inventaire équipable</h2><span class="label">${S.loot.length} tirages obtenus</span></div>${owned.length?owned.map(i=>`<div class="activity" style="margin-bottom:9px"><span class="symbol">${i.emoji}</span><div style="flex:1"><strong>${i.name}</strong><small>${i.rarity} · ${i.type==='title'?`Bonus +${((i.bonus||0)*100).toFixed(1)}%`:i.type==='pet'?'Compagnon visible':i.type==='habit'?'Vêtement':i.type==='weapon'?'Équipement de donjon':'Décoration'}</small></div>${button(eq[i.type]===i.id?'Équipé':'Équiper','equip-'+i.id,'btn alt sm',eq[i.type]===i.id)}</div>`).join(''):'<div class="empty">Ton inventaire est encore vide.</div>'}<div class="sect"><h2>Catalogue des trésors</h2></div><div class="grid2">${LOOT.map(i=>`<div class="tile"><span style="font-size:34px">${i.emoji}</span><strong class="tiny">${i.name}</strong>${pill(i.rarity,i.rarity==='Légendaire'?'gold':'')}</div>`).join('')}</div>`}
function marketsPage(){return `<div class="eyebrow">FINANCE VIRTUELLE</div><h1 class="top-title">Marchés & investissements</h1><p class="lead">Ce volet sera développé à partir d’une source gratuite de cours réels, sans argent réel.</p><div class="panel"><h2>Feuille de route</h2><p class="dim small">Bitcoin, Ethereum et autres actifs : les variations de prix devront refléter les évolutions du marché, avec affichage de la dernière actualisation et avertissement lorsque les données sont indisponibles.</p><div class="placeholder">Les achats et ventes ne sont pas activés dans cette V2 : aucun faux cours ne sera présenté comme un prix réel.</div></div><div class="panel"><h2>En attendant</h2><p class="dim small">Construis ton capital avec le cliqueur, les entreprises et les cinq jeux. Ton argent sera utilisable pour les marchés lorsqu'ils seront ajoutés.</p>${button('Construire mon empire','go-business','btn wide')}</div>`}
function garagePage(){return `<div class="eyebrow">COLLECTION AUTOMOBILE</div><h1 class="top-title">Mon garage</h1><p class="lead">Les véhicules achetés s'exposent ici. Chaque véhicule a désormais sa propre illustration. Pour exposer une voiture sur l’accueil, sélectionne « Exposer » après l’achat.</p><div class="panel">${scene('vehicle',{tier:premiumSelectedCar()<0?0:premiumSelectedCar(),color:S.carColor,label:premiumSelectedCar()<0?'Aperçu du garage':CARS[premiumSelectedCar()].name})}<div class="row" style="margin-top:12px"><strong>Couleur de carrosserie</strong><input id="car-color" type="color" value="${S.carColor}" style="height:38px;width:55px;border:0;background:none"></div></div><div class="sect"><h2>Catalogue</h2></div>${CARS.map((c,i)=>`<div class="business-row">${scene('vehicle',{tier:i,color:c.color,mini:true})}<div style="flex:1"><strong class="small">${c.name}</strong><div class="dim tiny">${fmt(c.price)}</div></div>${S.cars.includes(i)?button(S.featuredCar===i?'Exposé':'Exposer','premium-select-car-'+i,'btn sm'):button('Acheter','buy-car-'+i,'btn sm',S.cash<c.price)}</div>`).join('')}`}
function homesPage(){return `<div class="eyebrow">IMMOBILIER</div><h1 class="top-title">30 adresses, une seule ambition.</h1><p class="lead">Explore trente biens, du studio minuscule aux îles privées. Une propriété achetée reste disponible dans ta collection.</p>${HOMES.map((h,i)=>`<div class="panel"><div class="row"><div><h3>${h.name}</h3><div class="dim small">${h.area} m² · ${fmt(h.price)}</div></div>${S.home===i?pill('Domicile'):S.home>i?pill('Débloqué','blue'):''}</div><div style="margin:11px 0">${scene('room',{kind:i,label:h.area+' m²',mini:false})}</div>${button(S.home===i?'Domicile actuel':(S.ownedHomes||[]).includes(i)?'Habiter ici':'Acheter · '+fmt(h.price),'buy-home-'+i,'btn wide',S.home===i||(!(S.ownedHomes||[]).includes(i)&&S.cash<h.price))}</div>`).join('')}`}
function render(){if(game){renderGameShell();return}header();const fn={home:homePage,earn:earnPage,business:businessPage,games:gamesPage,life:lifePage,shop:shopPage,more:morePage,gacha:gachaPage,markets:marketsPage,garage:garagePage,homes:homesPage}[page]||homePage;$('#page').innerHTML=fn();document.querySelectorAll('#nav button').forEach(n=>n.classList.toggle('active',n.dataset.page===page||(page==='gacha'||page==='markets'?'more':page==='garage'||page==='homes'||page==='shop'?'life':false)));}
function go(p){if(window.Arcade)Arcade.stop();stopGame();page=p;closeModal();render();window.scrollTo(0,0)}
function openModal(t,body){modal=t;$('#modal-root').innerHTML=`<div class="modal-shade" data-action="close-out"><div class="modal"><div class="notch"></div><div class="modal-header"><h2 style="margin:0;font:900 20px Outfit">${t}</h2><button class="close" data-action="close">×</button></div>${body}</div></div>`}
function closeModal(){modal='';$('#modal-root').innerHTML=''}
function catalog(){openModal('Fonder une entreprise',`<p class="dim small">Choisis ton prochain investissement. Revenus automatiques par seconde, sans impôt.</p>${BIZ.map(b=>`<div class="catalog-item">${scene('business',{mini:true,biz:b,level:1})}<div style="flex:1;min-width:0"><strong class="small">${b.name}</strong><div class="dim tiny">${b.desc}</div><div style="color:var(--mint);font-size:11px;margin:5px 0">+${fmt(b.income)}/s</div><div class="row"><strong class="small">${fmt(b.cost)}</strong>${button('Fonder','found-'+b.id,'btn sm',S.cash<b.cost)}</div></div></div>`).join('')}`)}
function bizDetail(id){const b=BIZ.find(x=>x.id===id),x=S.biz[id];if(!x)return;const cost=Math.round(b.cost*.7*Math.pow(1.85,x.level-1)*Math.max(1,x.count*.75)),duplicate=Math.round(b.cost*Math.pow(1.68,x.count));openModal(b.name,`${scene('business',{biz:b,level:x.level,label:['Départ','Développement','Expansion','Prestige','Empire'][buildingStage(x.level)-1]})}<div style="margin-top:13px" class="grid2">${boxstat('Niveau',x.level)}${boxstat('Revenus / s',fmt(b.income*Math.pow(1.63,x.level-1)*x.count))}</div><div class="panel" style="margin-top:13px"><div class="row"><div><h3>Améliorer</h3><div class="dim small">Revenus ×1,63. Un nouveau bâtiment apparaît aux niveaux 5, 10, 15 et 20. Maximum : 20.</div></div></div><div class="progress" style="margin:11px 0"><i style="width:${Math.min(100,(x.level%5)/5*100)}%"></i></div>${button(x.level>=20?'Niveau maximal':'Améliorer · '+fmt(cost),'biz-up-'+id,'btn wide',x.level>=20||S.cash<cost)}</div><div class="panel"><div class="row"><div><h3>Ouvrir un second site</h3><div class="dim small">Établissements : ${x.count}</div></div>${button('+'+fmt(duplicate),'biz-copy-'+id,'btn sm',S.cash<duplicate)}</div></div>`)}
function gachaRoll(){if(!spend(120))return;const r=Math.random(),rarity=r<.48?'Commun':r<.78?'Rare':r<.95?'Épique':r<.998?'Légendaire':'Administrateur',items=LOOT.filter(x=>x.rarity===rarity),item=items[Math.floor(Math.random()*items.length)];S.loot.push(item.id);S.gacha++;persist();openModal('Invocation réussie',`<div class="reward" style="padding:24px"><div class="big" style="font-size:84px;animation:lootReveal .8s ease-out">${item.emoji}</div><h2>${item.name}</h2>${pill(item.rarity,item.rarity==='Légendaire'?'gold':'')}<p class="dim small">${item.type==='pet'?'Ce compagnon peut apparaître près de ta maison.':item.type==='title'?'Ce titre peut modifier légèrement tes revenus.':'Cet objet peut être équipé ou exposé.'}</p>${button('Équiper','equip-'+item.id,'btn wide')} ${button('Plus tard','close','btn alt wide')}</div>`)}
function openDemo(){
 const steps=[1,5,10,15,20];
 const artRow=(a)=>`<div class="evolution-five">${steps.map((n,i)=>`<figure><img loading="lazy" src="art/${a(i)}.webp" alt="Palier ${n}"><figcaption> Niveau ${n}</figcaption></figure>`).join('')}</div>`;
 const jobs=JOBS.map((j,i)=>`<div class="evolution-group"><h3>${e(j.name)} <small>· Cliqueur</small></h3>${artRow(k=>'job_'+i+'_'+k)}</div>`).join('');
 const businesses=BIZ.map(b=>`<div class="evolution-group"><h3>${e(b.name)} <small>· Entreprise</small></h3>${artRow(k=>'biz_'+b.id+'_'+k)}</div>`).join('');
 openModal('Galerie de progression · 105 visuels',`<p class="dim small">Les cinq paliers de chaque activité sont disponibles ici pour comparaison, sans modifier ta sauvegarde.</p><h2>7 métiers actifs</h2>${jobs}<h2>14 entreprises passives</h2>${businesses}<button data-action="close" class="btn wide">Fermer la galerie</button>`)
}
function downloadSave(){const blob=new Blob([JSON.stringify({...S,last:Date.now()},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='life-empire-v4-sauvegarde.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast('Sauvegarde exportée')}
function importSave(file){const reader=new FileReader();reader.onload=()=>{try{const x=JSON.parse(reader.result);if(!x||typeof x.cash!=='number'||typeof x.biz!=='object'||!x.avatar||!Array.isArray(x.cars))throw Error('Format invalide');if(!confirm('Remplacer la partie actuelle par cette sauvegarde ?'))return;S={...initial(),...x,last:Date.now()};if(!Array.isArray(x.ownedHomes)){const prior=[0,2,5,7,13,21,26,29];S.home=(x.home||0)<8?prior[x.home||0]:x.home;S.ownedHomes=Array.from({length:S.home+1},(_,i)=>i)}persist();go('home');toast('Sauvegarde restaurée')}catch(err){toast('Fichier de sauvegarde invalide')}};reader.readAsText(file)}
const action=(v,el)=>{if(window.Arcade&&Arcade.action(v))return;if(v.startsWith('equip-')){const id=v.slice(6),item=LOOT.find(i=>i.id===id);if(item&&S.loot.includes(id)){safeEquip()[item.type]=id;persist();closeModal();render();toast(item.name+' équipé !')}return}if(v==='close'||v==='close-out'){if(v==='close-out'&&el!==el.closest('.modal-shade'))return;closeModal();return}if(v.startsWith('premium-select-car-')){const i=Number(v.slice(19));if(S.cars.includes(i)){S.featuredCar=i;persist();render();toast(CARS[i].name+' exposé dans ton garage')}return}if(v==='premium-next-car'||v==='premium-prev-car'){const owned=Array.isArray(S.cars)?S.cars:[];if(owned.length){const ci=premiumSelectedCar();S.featuredCar=owned[(owned.indexOf(ci)+(v==='premium-next-car'?1:owned.length-1))%owned.length];persist();render()}else go('garage');return}if(v==='daily'){const today=new Date().toLocaleDateString('fr-CA');if(S.dailyClaim!==today){S.dailyClaim=today;inc(25);render();toast('+25 € · Bonus du jour')}return}if(v==='tap'){const val=JOBS[S.job].gain*S.clickLvl*titleMult();inc(val);S.taps++;const p=el.getBoundingClientRect(),f=document.createElement('span');f.className='floater';f.textContent='+'+fmt(val);f.style.left=40+Math.random()*35+'%';f.style.top='55%';el.appendChild(f);setTimeout(()=>f.remove(),900);const c=$('.amount');if(c)c.textContent=fmt(S.cash);return}if(v==='click-up'){const c=Math.round(18*Math.pow(1.68,S.clickLvl-1)*Math.pow(2.2,S.job));if(spend(c)){S.clickLvl++;render()}return}if(v==='unlock-job'){const n=JOBS[S.job+1];if(n&&spend(n.price)){S.job++;S.clickLvl=1;render();toast('Nouveau métier : '+n.name)}return}if(v==='open-catalog'){catalog();return}if(v.startsWith('found-')){const id=v.slice(6),b=BIZ.find(x=>x.id===id);if(b&&spend(b.cost)){if(S.biz[id])S.biz[id].count++;else S.biz[id]={count:1,level:1};persist();closeModal();render();toast(b.name+' créée !')}return}if(v==='biz-detail'){bizDetail(el.dataset.id);return}if(v.startsWith('biz-up-')){const id=v.slice(7),b=BIZ.find(x=>x.id===id),x=S.biz[id];if(!b||!x)return;const c=Math.round(b.cost*.7*Math.pow(1.85,x.level-1)*Math.max(1,x.count*.75));if(x.level>=20){toast('Niveau maximal : 20');return}if(spend(c)){x.level++;persist();bizDetail(id);toast('Entreprise améliorée !')}return}if(v.startsWith('biz-copy-')){const id=v.slice(9),b=BIZ.find(x=>x.id===id),x=S.biz[id];if(!b||!x)return;const c=Math.round(b.cost*Math.pow(1.68,x.count));if(spend(c)){x.count++;persist();bizDetail(id);toast('Nouvel établissement !')}return}if(v==='gacha-roll'){gachaRoll();return}if(v==='reset'){if(confirm('Supprimer cette progression V4 ? Exporte ta sauvegarde avant si tu veux la conserver.')){S=initial();persist();go('home');toast('Nouvelle partie créée')}return}if(v==='demo'){openDemo();return}if(v==='export'){downloadSave();return}if(v==='import'){$('#import-file')?.click();return}if(v.startsWith('shop-')){const i=+v.slice(5),prices=[450,2500,8000,30000,160000,750000],variants=[3,0,7,6,9,11];if((S.shop||[]).includes(i)||spend(prices[i])){S.shop=S.shop||[];if(!S.shop.includes(i))S.shop.push(i);S.avatar.outfit=Math.floor(variants[i]/2);S.avatar.hair=variants[i]%2;S.equipped.habit='shop_'+i;persist();render();toast('Tenue équipée !')}return}if(v==='homes'){go('homes');return}if(v==='garage'){go('garage');return}if(v==='go-life'){go('life');return}if(v==='go-shop'){go('shop');return}if(v==='go-business'){go('business');return}if(v==='go-gacha'){go('gacha');return}if(v.startsWith('buy-home-')){const i=+v.slice(9);if((S.ownedHomes||[]).includes(i)){S.home=i;persist();render();toast('Logement sélectionné !')}else if(spend(HOMES[i].price)){S.home=i;S.ownedHomes=S.ownedHomes||[0];S.ownedHomes.push(i);persist();render();toast('Bienvenue dans ton nouveau logement !')}return}if(v.startsWith('buy-car-')){const i=+v.slice(8);if(!S.cars.includes(i)&&spend(CARS[i].price)){S.cars.push(i);S.featuredCar=i;S.carColor=CARS[i].color;persist();render();toast('Véhicule ajouté au garage !')}return}if(v.startsWith('start-')){const id=v.slice(6);if(id==='basket'){openModal('Basket Rush — Choisis ton mode',`<div class="grid2"><div class="tile">🏀<strong>Mode A : Shoot 2.5D</strong><p class="dim small">Glisse vers le panier et dose la puissance.</p>${button('Lancer','play-basket','btn wide')}</div><div class="tile">⛹️<strong>Mode B : Mini-match</strong><p class="dim small">Déplace-toi, marque et défends en plein écran.</p>${button('Jouer','play-match','btn wide')}</div></div>`)}else launchGame(id);return}if(v==='play-match'){openModal('Choisis ton basketteur',`<div class="grid3">${[['❄','Glacier','Gel'],['⚡','Éclair','Thunder Dunk'],['🛡','Gardien','Panier gelé']].map((x,i)=>`<div class="tile center"><div style="font-size:38px">${x[0]}</div><strong>${x[1]}</strong><div class="tiny dim">${x[2]}</div>${button('Choisir','hero-'+i,'btn sm')}</div>`).join('')}</div>`);return}if(v.startsWith('hero-')){launchGame('match');game.hero=+v.slice(5);return}if(v.startsWith('play-')){launchGame(v.slice(5));return}if(v==='exit-game'){stopGame();go('games');return}if(v==='restart-game'){const id=game?.id;launchGame(id);return}if(v==='cyber-levels'){cyberLevels();return}if(v.startsWith('cyber-stage-')){const lvl=+v.slice(12),max=Math.min(5,(S.progress?.cyberStage||0)+1);if(lvl>max){toast('Niveau verrouillé');return}launchGame('cyber');game.stage=lvl;game.doors={};game.solved=0;game.gx=1;game.gy=1;updateCyberUI();return}if(v==='solve-cyber'){const pick=+el.dataset.answer;solveCyber(pick);return}if(v==='dungeon-up'||v==='forge-weapon'){upgradeDungeon('weapon');return}if(v==='forge-armor'){upgradeDungeon('armor');return}if(v==='dungeon-heal'){if(game&&game.id==='dungeon')runControl('potion');updateDungeonUI();return}if(v==='dungeon-bag'){if(game&&game.id==='dungeon')openModal('Sac de l’aventurier',`<div class="grid2">${boxstat('Cristaux',game.materials)}${boxstat('Potions',game.potions)}${boxstat('Épée',game.weapon)}${boxstat('Armure',game.armor)}</div><p class="dim">Les objets d’arme obtenus au gacha peuvent être exposés ici. Élimine les monstres pour gagner des cristaux et améliorer tes équipements.</p>`);return}if(v==='surv-craft'){craftSurvival();return}if(v.startsWith('craft-')){craftSurvival(v.slice(6));return}}
