document.addEventListener('change',ev=>{if(ev.target.dataset.avatar){S.avatar[ev.target.dataset.avatar]=+ev.target.value;persist();render()}if(ev.target.id==='car-color'){S.carColor=ev.target.value;persist();render()}if(ev.target.id==='import-file'&&ev.target.files[0])importSave(ev.target.files[0])});
