// --- ARCADE ENGINE: five distinct games, including both basket modes ---
function renderGameShell(){document.body.classList.add('playing');const names={basket:'BASKET RUSH · SHOOT',match:'BASKET RUSH · MATCH',cyber:'CYBER LAB · ICAM',dungeon:'DUNGEON HUNTER',runner:'SKYLINE RUNNER',survival:'SURVIVAL ISLAND'};$('#page').innerHTML=`<div class="row"><div><div class="eyebrow">LIFE EMPIRE ARCADE</div><h1 class="top-title" style="font-size:23px">${names[game.id]}</h1></div>${button('✕ Quitter','exit-game','btn ghost sm')}</div><div id="game-hud" class="game-hud"></div><div class="play-container"><canvas id="game-canvas" width="360" height="500"></canvas><div id="game-overlay" class="game-overlay hide"></div></div><div id="game-instructions" class="dim small center"></div><div id="game-extra"></div><div class="game-controls" id="game-controls"></div>`;const c=$('#game-canvas');game.ctx=c.getContext('2d');game.canvas=c;game.rect=c.getBoundingClientRect();if(game.id==='basket'){game.tip='Glisse depuis le ballon vers le haut pour viser et tirer.'}else if(game.id==='match'){game.tip='Match de côté : saute, dribble et tire. Attrape le jeton central pour ton pouvoir !'}else if(game.id==='runner'){game.tip='Touche l’écran ou SAUT pour franchir les obstacles.'}else{game.tip='Déplace ton personnage avec les flèches ou le clavier.'};$('#game-instructions').textContent=game.tip;setupControls();c.addEventListener('pointerdown',gamePointerDown);c.addEventListener('pointerup',gamePointerUp);c.addEventListener('pointermove',gamePointerMove);if(game.id==='cyber'){updateCyberUI();$('#game-extra').insertAdjacentHTML('beforebegin',`<button class="btn alt sm" data-action="cyber-levels">☷ Choisir un niveau</button>`)}if(game.id==='dungeon')updateDungeonUI();if(game.id==='survival')updateSurvivalUI()}
function launchGame(id){if(!['basket','match','cyber','dungeon','runner','survival'].includes(id))return;stopGame();closeModal();page='games';const common={id,ctx:null,canvas:null,time:0,score:0,won:false,over:false,moving:0,last:performance.now(),pointer:null};game=Object.assign(common,id==='basket'?{shots:0,ball:null,aim:null,hoopX:180,hoopY:165,mode:'shoot',distance:0}:id==='match'?{px:100,py:365,vy:0,onGround:true,ballX:114,ballY:360,enemyX:275,enemyY:365,enemyVX:0,enemyPoints:0,shots:0,cooldown:0,move:null,owner:'player',ball:null,hero:0,power:0,powerTimer:0,freeze:0,defend:0,token:0,tokenActive:false,tokenX:180,jumpHeld:false,dribble:0,look:1}:id==='cyber'?{gx:1,gy:1,doors:{},solved:0,tries:0,puzzle:null,maze:makeMaze(),stage:Math.min(5,(S.progress?.cyberStage||0)+1)}:id==='dungeon'?{px:180,py:270,hp:100,maxHp:100,lv:S.dungeonSave?.level||1,xp:S.dungeonSave?.xp||0,kills:0,weapon:Math.max(1,S.dungeonSave?.weapon||1),armor:S.dungeonSave?.armor||0,materials:S.dungeonSave?.materials||0,attack:0,enemies:[],spawn:0,move:null,zone:Math.min(3,S.dungeonSave?.quest||0),chest:0,potions:2,questKill:8,invOpen:false,slash:0,boss:null}:id==='runner'?{x:66,y:395,vy:0,platformY:414,obstacles:[],spawn:0,speed:145,dist:0,score:0}: {px:182,py:262,wood:0,stone:0,food:0,ore:0,rope:0,fire:S.survivalSave?.camp||0,shelter:0,tool:0,energy:100,turns:0,resources:makeResources(),move:null,day:1,crafted:0,regenTimer:0,bench:0,water:0});if(id==='cyber')game.stage=Math.min(5,(S.progress?.cyberStage||0)+1);renderGameShell();lastClock=performance.now();raf=requestAnimationFrame(gameLoop);window.scrollTo(0,0)}
function stopGame(){if(game&&game.id==='dungeon'){S.dungeonSave={level:game.lv,xp:game.xp,weapon:game.weapon,armor:game.armor,materials:game.materials,quest:game.zone};persist()}cancelAnimationFrame(raf);game=null;activeKeys.clear();document.body.classList.remove('playing')}
const rand=(min,max)=>min+Math.random()*(max-min),clamp=(n,a,b)=>Math.min(b,Math.max(a,n));
function circle(ctx,x,y,r,color,stroke=null){ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fillStyle=color;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=2;ctx.stroke()}}
function round(ctx,x,y,w,h,r,col,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fillStyle=col;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=2;ctx.stroke()}}
function poly(ctx,pts,color,stroke){ctx.beginPath();ctx.moveTo(...pts[0]);pts.slice(1).forEach(p=>ctx.lineTo(...p));ctx.closePath();ctx.fillStyle=color;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=2;ctx.stroke()}}
function label(ctx,s,x,y,size=13,color='#eaf1ee',align='left'){ctx.font=`800 ${size}px system-ui`;ctx.fillStyle=color;ctx.textAlign=align;ctx.fillText(s,x,y);ctx.textAlign='left'}
function isoBlock(ctx,x,y,w,h,d,top='#bfc9bf',side='#576f75'){poly(ctx,[[x,y],[x+w,y-h],[x+w+d,y-h+d*.42],[x+d,y+d*.42]],top);poly(ctx,[[x,y],[x+d,y+d*.42],[x+d,y+d*.42+23],[x,y+23]],side);poly(ctx,[[x+d,y+d*.42],[x+w+d,y-h+d*.42],[x+w+d,y-h+d*.42+23],[x+d,y+d*.42+23]],'#405761')}
function bkg(ctx,top,bottom){const grad=ctx.createLinearGradient(0,0,0,500);grad.addColorStop(0,top);grad.addColorStop(1,bottom);ctx.fillStyle=grad;ctx.fillRect(0,0,360,500)}
function player(ctx,x,y,color='#73b6bc',scale=1){circle(ctx,x,y+8*scale,12*scale,'#071d2790');round(ctx,x-9*scale,y-10*scale,18*scale,26*scale,7*scale,color);circle(ctx,x,y-19*scale,10*scale,'#dba981');ctx.fillStyle='#293744';ctx.fillRect(x-8*scale,y-26*scale,16*scale,6*scale);circle(ctx,x-3*scale,y-19*scale,1.2*scale,'#28313e');circle(ctx,x+3*scale,y-19*scale,1.2*scale,'#28313e')}
function gameLoop(now){if(!game)return;const dt=Math.min(.045,(now-lastClock)/1000||0);lastClock=now;game.time+=dt;updateGame(dt);if(!game)return;drawGame(game.ctx);refreshHud();raf=requestAnimationFrame(gameLoop)}
function refreshHud(){if(!game)return;const g=game,h={basket:`Tirs : <strong>${g.shots}/10</strong> · Score : <strong>${g.score}</strong> · Distance : ${g.distance+1}`,match:`${g.score} — ${g.enemyPoints} · ${Math.max(0,Math.ceil(75-g.time))} s · ${['Glace','Thunder','Bouclier'][g.hero]}`,cyber:`Niveau <strong>${g.stage}</strong> · Portes : <strong>${g.solved}/${Math.min(5,2+g.stage)}</strong>`,dungeon:`Zone ${g.zone+1} · LV <strong>${g.lv}</strong> · PV <strong>${Math.ceil(g.hp)}</strong> · Kills <strong>${g.kills}/${g.questKill}</strong>`,runner:`Distance : <strong>${Math.floor(g.dist)} m</strong> · Record : ${S.best.runner||0}`,survival:`Bois ${g.wood} · Pierre ${g.stone} · Minerai ${g.ore} · Feu ${g.fire} · Abri ${g.shelter}`};const el=$('#game-hud');if(el)el.innerHTML=h[g.id]}
function updateGame(dt){const g=game;if(g.over)return;
if(g.id==='basket'){if(g.ball){g.ball.t+=dt*1.3;const t=g.ball.t;if(t>=1){const hit=Math.abs(g.ball.targetX-g.hoopX)<23&&Math.abs(g.ball.power-(.68+g.distance*.06))<.17;if(hit){g.score+=3;inc(12);toast('PANIER ! SCORE '+g.score+' · +12 €')}else toast('Tir raté');g.shots++;g.distance=Math.min(3,Math.floor(g.shots/3));g.hoopX=180+Math.sin(g.shots*1.7)*g.distance*26;g.ball=null;if(g.shots>=10)finishGame('basket',g.score,'Série terminée !')}}}
else if(g.id==='match'){if(g.dunk){g.dunk.t+=dt*2.3;const t=Math.min(1,g.dunk.t);g.px=g.dunk.start+(309-g.dunk.start)*t;g.py=365-210*Math.sin(Math.PI*t);if(t>=1){g.dunk=null;g.py=365;g.score+=2;inc(16)}}if(g.time>=75){finishGame('match',g.score,'Fin du match !');return}const dir=getMove(g);if(!g.dunk)g.px=clamp(g.px+dir.x*180*dt,22,338);g.vy+=950*dt;if(!g.dunk)g.py+=g.vy*dt;if(!g.dunk&&g.py>=365){g.py=365;g.vy=0;g.onGround=true}if(Math.abs(dir.x)>.1)g.look=Math.sign(dir.x);if(g.freeze<=0)g.enemyX+=clamp((g.owner==='enemy'?90:g.px)-g.enemyX,-1,1)*Math.min(96,65+g.time*.12)*dt;if(g.enemyX<25)g.enemyX=25;if(g.enemyX>335)g.enemyX=335;g.cooldown=Math.max(0,g.cooldown-dt);g.powerTimer=Math.max(0,g.powerTimer-dt);g.freeze=Math.max(0,g.freeze-dt);g.defend=Math.max(0,g.defend-dt);g.dribble=Math.max(0,g.dribble-dt);if(g.owner==='player'&&g.dribble===0&&Math.abs(g.enemyX-g.px)<26&&g.py>320&&g.freeze<=0){g.owner='enemy';g.dribble=2;toast('Ballon intercepté !')}if(g.owner==='enemy'){if(g.freeze<=0)g.enemyX-=35*dt;if(g.enemyX<90&&g.cooldown<=0){g.cooldown=2.5;g.enemyPoints+=g.defend>0?0:2;g.owner='player';g.px=110;g.py=365;g.enemyX=275;toast(g.defend>0?'Panier protégé !':'Panier adverse !')}if(Math.abs(g.px-g.enemyX)<22&&g.dribble<=0){g.owner='player';g.dribble=1.5;toast('Interception !')}}if(g.ball){g.ball.t+=dt*2;if(g.ball.t>=1){if(g.ball.goal){if(g.ball.who==='player')g.score+=2;else if(g.defend===0)g.enemyPoints+=2;if(g.ball.who==='player')inc(12);toast(g.ball.who==='player'?'PANIER ! +12 €':'Panier adverse');}else toast('Tir manqué');g.ball=null;g.owner='player';g.px=95;g.py=365;g.enemyX=271;g.dribble=1.1}}if(g.time>=g.token+8){g.token=g.time;g.tokenActive=true}if(g.tokenActive&&Math.abs(g.px-g.tokenX)<29&&g.py>285){g.tokenActive=false;g.power=1;toast('POUVOIR CHARGÉ !')}}
else if(g.id==='dungeon'){const dir=getMove(g);g.px=clamp(g.px+dir.x*124*dt,18,342);g.py=clamp(g.py+dir.y*124*dt,55,473);g.spawn-=dt;g.attack-=dt;g.slash=Math.max(0,g.slash-dt);if(g.spawn<=0&&g.enemies.length<15){g.spawn=Math.max(.56,1.8-g.zone*.26);g.enemies.push({x:rand(30,330),y:rand(75,164),hp:2+g.zone*2+Math.floor(g.lv/3),max:2+g.zone*2+Math.floor(g.lv/3),phase:rand(0,6),kind:Math.random()<.2?'elite':'slime'})}g.enemies.forEach(z=>{const a=Math.atan2(g.py-z.y,g.px-z.x);z.x+=Math.cos(a)*dt*(31+g.zone*9);z.y+=Math.sin(a)*dt*(31+g.zone*9);if(Math.hypot(g.px-z.x,g.py-z.y)<24){g.hp-=(10+g.zone*4)*dt*(1-.08*g.armor)}});if(g.attack<=0){const near=g.enemies.filter(z=>Math.hypot(g.px-z.x,g.py-z.y)<45+g.weapon*7).sort((a,b)=>Math.hypot(g.px-a.x,g.py-a.y)-Math.hypot(g.px-b.x,g.py-b.y))[0];if(near){near.hp-=1+g.weapon*.7;g.attack=.3;g.slash=.2;if(near.hp<=0){g.enemies.splice(g.enemies.indexOf(near),1);g.kills++;g.xp+=5+g.zone*2;g.materials+=(Math.random()<.55?1:0);inc(3+g.zone*2);if(g.xp>=g.lv*17){g.xp=0;g.lv++;g.maxHp+=4;g.hp=Math.min(g.maxHp,g.hp+35);toast('Niveau '+g.lv+' !')}}}}if(g.kills>=g.questKill){g.zone=Math.min(3,g.zone+1);g.questKill+=8+g.zone*3;g.hp=g.maxHp;g.materials+=3;S.dungeonSave={level:g.lv,xp:g.xp,weapon:g.weapon,armor:g.armor,materials:g.materials,quest:g.zone};persist();toast('QUÊTE ACCOMPLIE · NOUVELLE ZONE !');updateDungeonUI()}if(g.hp<=0){S.dungeonSave={level:g.lv,xp:g.xp,weapon:g.weapon,armor:g.armor,materials:g.materials,quest:g.zone};persist();finishGame('dungeon',g.kills,'Ton aventurier est épuisé.')}}
else if(g.id==='runner'){g.dist+=dt*g.speed/7;g.speed=Math.min(225,145+g.dist*.04);g.vy+=970*dt;const prev=g.y;g.y+=g.vy*dt;g.spawn-=dt;if(g.spawn<=0){g.spawn=rand(.85,1.7);g.obstacles.push({x:390,w:rand(25,42),h:rand(25,73),type:(()=>{const n=Math.random();return n<.27?1:n<.45?2:n<.58?3:n<.70?4:0})()})}g.obstacles.forEach(z=>z.x-=g.speed*dt);g.obstacles=g.obstacles.filter(z=>z.x>-80);let platform=false;for(const z of g.obstacles){const collideX=g.x+11>z.x&&g.x-11<z.x+z.w,top=414-z.h;if(!collideX)continue;if(z.type===4){if(g.y+18>top){g.obstacles.splice(g.obstacles.indexOf(z),1);inc(9);toast('Orbe collectée +9 €')}continue}if(z.type===3){if(prev+18<=top+7&&g.vy>=0){g.y=top-18;g.vy=-510;continue}}if(z.type===1||z.type===2){if(g.y+18>top&&g.y-18<414){finishGame('runner',Math.floor(g.dist),z.type===2?'Drone rencontré !':'Attention aux pics !');return}}else if(prev+18<=top+6&&g.y+18>=top&&g.vy>=0){g.y=top-18;g.vy=0;platform=true}else if(g.y+15>top&&g.y-12<414&&g.y+18>top+6){finishGame('runner',Math.floor(g.dist),'Collision latérale !');return}}if(g.y>=395){g.y=395;g.vy=0}if(g.y<395&&g.vy===0&&!platform){g.vy=1}}
else if(g.id==='survival'){const dir=getMove(g);g.px=clamp(g.px+dir.x*107*dt,25,335);g.py=clamp(g.py+dir.y*107*dt,70,453);g.energy=Math.max(0,g.energy-dt*(g.shelter?0.38:.8));g.day=1+Math.floor(g.time/75);g.regenTimer=(g.regenTimer||0)+dt;if(g.regenTimer>=10){g.regenTimer=0;for(const kind of ['tree','rock','food','ore','fiber']){const left=g.resources.filter(z=>!z.used&&z.kind===kind).length;if(left<2){for(let i=0;i<5;i++)g.resources.push({x:rand(32,330),y:rand(130,440),kind,used:false})}}}if(g.energy<=0)finishGame('survival',g.turns+g.crafted*5,'Tu dois te reposer.')}
}
function finishGame(id,score,message){const g=game;if(!g||g.over)return;g.over=true;const best=Math.max(S.best[id]||0,score);S.best[id]=best;const reward=id==='basket'?0:id==='match'?g.score*6:id==='cyber'?0:id==='dungeon'?Math.round(score*2):id==='runner'?Math.round(score*.15):Math.round(score*5);if(reward>0)inc(reward);persist();const p=$('#game-overlay');if(p){p.classList.remove('hide');p.innerHTML=`<div><div class="eyebrow">PARTIE TERMINÉE</div><h2>${message}</h2><p>Score : <strong>${score}</strong> · Record : <strong>${best}</strong></p><p style="color:#c2e6bd">Récompense finale : +${fmt(reward)}</p>${id==='cyber'&&g.stage<5?button('Niveau suivant →','cyber-stage-'+(g.stage+1),'btn'):''} ${button('Rejouer','restart-game','btn')} ${button('Retour aux jeux','exit-game','btn alt')}</div>`}}
function drawGame(c){if(!game)return;switch(game.id){case'basket':drawBasket(c);break;case'match':drawMatch(c);break;case'cyber':drawCyber(c);break;case'dungeon':drawDungeon(c);break;case'runner':drawRunner(c);break;case'survival':drawSurvival(c);break}}
function court(c){bkg(c,'#243f53','#2a4850');poly(c,[[30,150],[330,150],[355,480],[5,480]],'#bc8560','#efd19c');for(let i=0;i<10;i++){c.strokeStyle='#cf98736c';c.lineWidth=1;c.beginPath();c.moveTo(30,150+i*36);c.lineTo(330,150+i*36);c.stroke()}c.strokeStyle='#e9cead';c.lineWidth=3;c.beginPath();c.moveTo(180,151);c.lineTo(180,482);c.moveTo(70,300);c.lineTo(290,300);c.arc(180,300,52,0,Math.PI*2);c.stroke();round(c,146,97,68,41,4,'#dfe9ec','#bed6dc');c.strokeStyle='#e9e3d2';c.lineWidth=4;c.strokeRect(153,100,54,31);c.beginPath();c.ellipse(180,164,28,9,0,0,Math.PI*2);c.strokeStyle='#d3704d';c.lineWidth=5;c.stroke();}
function basketBall(c,x,y,r=15){circle(c,x,y,r,'#e48e4c','#422d2b');c.strokeStyle='#73402d';c.lineWidth=2;c.beginPath();c.moveTo(x-r,y);c.lineTo(x+r,y);c.moveTo(x,y-r);c.lineTo(x,y+r);c.arc(x,y,r*.8,-Math.PI/3,Math.PI/3);c.stroke()}
function drawBasket(c){court(c);const g=game;label(c,'10 TIRS · VISE ET DOSE LA PUISSANCE',180,34,12,'#f8d9a9','center');label(c,'Distance '+(g.distance+1),180,54,12,'#fff1cd','center');if(g.ball){const t=g.ball.t,x=180+(g.ball.targetX-180)*t,y=412+(g.hoopY-412)*t-145*4*t*(1-t),r=16*(1-.57*t);circle(c,x+7,y+20,Math.max(4,r),'#342b3144');basketBall(c,x,y,r)}else basketBall(c,180,417,17);if(g.pointer){const o=g.pointer;c.strokeStyle='#ffe5ad';c.setLineDash([7,6]);c.lineWidth=3;c.beginPath();c.moveTo(180,420);c.lineTo(o.x2,o.y2);c.stroke();c.setLineDash([]);label(c,'RELÂCHE POUR TIRER',180,463,12,'#fff3d3','center')}else label(c,'GLISSE LE BALLON VERS LE PANIER',180,470,11,'#f8e9ca','center');if(g.distance){round(c,136,95,88,45,2,'#dbe6e6');round(c,145,105,70,22,2,'#829eb0');c.beginPath();c.ellipse(g.hoopX,165,24,8,0,0,Math.PI*2);c.strokeStyle='#e49a70';c.lineWidth=5;c.stroke()}}
function drawMatch(c){const g=game;bkg(c,'#253d54','#152735');round(c,0,392,360,108,0,'#bf8b5e');round(c,0,386,360,9,0,'#f2d7a9');for(let i=0;i<9;i++){c.strokeStyle='#d7a87a66';c.beginPath();c.moveTo(i*45,393);c.lineTo(i*45,498);c.stroke()}for(const [x,dir] of [[25,1],[335,-1]]){round(c,x-7,104,14,160,3,'#b4cbd0');round(c,x+(dir===1?0:-39),155,39,45,2,'#dae7e8','#fff');c.beginPath();c.ellipse(x+dir*30,201,23,7,0,0,Math.PI*2);c.strokeStyle='#d66b45';c.lineWidth=5;c.stroke()}label(c,`${g.score}  :  ${g.enemyPoints}`,180,58,31,'#f8e3b8','center');label(c,'MATCH · 75s',180,83,12,'#bcd2d3','center');const drawChar=(x,y,col,ball)=>{circle(c,x,y+12,18,'#071a2880');round(c,x-14,y-34,28,36,9,col);circle(c,x,y-47,13,'#e1b193');round(c,x-12,y+1,9,19,3,'#263d57');round(c,x+3,y+1,9,19,3,'#263d57');if(ball)basketBall(c,x+18,y-26,9)};drawChar(g.enemyX,g.enemyY,'#b45a5b',g.owner==='enemy');drawChar(g.px,g.py,'#4e9eaf',g.owner==='player');if(g.ball){const t=g.ball.t;const x=g.ball.sx+(g.ball.tx-g.ball.sx)*t;const y=g.ball.sy+(g.ball.ty-g.ball.sy)*t-115*4*t*(1-t);basketBall(c,x,y,9)}if(g.tokenActive){circle(c,g.tokenX,334,15,'#f2d178','#fff0ae');label(c,'✦',g.tokenX,339,17,'#77572d','center')}if(g.dunk){for(let j=0;j<4;j++){const xx=g.px-8-j*10,yy=g.py+20+j*8;c.beginPath();c.moveTo(xx,yy);c.lineTo(xx-9,yy+13);c.lineTo(xx+4,yy+8);c.strokeStyle='#ffd079';c.lineWidth=3;c.stroke()}}if(g.defend>0){round(c,0,150,65,87,12,'#8adbe5a5','#dbf8fa');label(c,'❄',35,190,25,'#fff','center')}if(g.freeze>0)label(c,'GELÉ !',g.enemyX,g.enemyY-68,16,'#b1efff','center');if(g.power)label(c,'POUVOIR DISPONIBLE',180,124,15,'#ffe39d','center')}
const MAZE=['###########','#...#.....#','#.#.#.###.#','#.#...#...#','#.#####.#.#','#.....#.#.#','#####.#.#.#','#...#...#.#','#.#.#####.#','#.........#','###########'];
const doorsMap={'3,1':0,'5,3':1,'9,3':2,'5,7':3,'8,9':4};
function makeMaze(){return MAZE.map(s=>s.split(''))}
const puzzles=[{q:'Résous : 3x + 5 = 26',a:['x = 5','x = 7','x = 9'],ok:1},{q:'En Python, len([2, 4, 6]) vaut…',a:['2','3','6'],ok:1},{q:'La dérivée de x² est…',a:['2x','x','2'],ok:0},{q:'Unité de la tension électrique ?',a:['Ampère','Volt','Ohm'],ok:1},{q:'Calcul : 2³ × 2² = ?',a:['16','32','64'],ok:1}];
function levelPuzzles(l){const variants=[puzzles,[{q:'5x - 4 = 21. Quelle valeur de x ?',a:['4','5','6'],ok:1},{q:'Dans une boucle for, range(4) produit…',a:['0,1,2,3','1,2,3,4','0,1,2,3,4'],ok:0},{q:'Dérivée de sin(x) ?',a:['sin(x)','cos(x)','-sin(x)'],ok:1},{q:'Dimension d’une force ?',a:['kg·m/s²','kg/s','W'],ok:0},{q:'2⁵ vaut ?',a:['16','32','64'],ok:1}],[{q:'3² + 4² = ?',a:['25','49','12'],ok:0},{q:'Résistance : U=12 V, I=3 A',a:['4 Ω','9 Ω','36 Ω'],ok:0},{q:'Python : 2**3 ?',a:['6','8','9'],ok:1},{q:'Vecteurs perpendiculaires : produit scalaire ?',a:['1','0','-1'],ok:1},{q:'Un oscillateur amorti perd de…',a:['Énergie','Masse','Charge'],ok:0}]];return variants[(l-1)%variants.length]}

function drawCyber(c){const g=game;const themes=[['#243b43','#151c33'],['#733f56','#37283d'],['#314d4b','#132832'],['#463859','#211e39'],['#665343','#292a37']];bkg(c,...themes[(g.stage-1)%themes.length]);const cell=29.5,ox=18,oy=89;label(c,['DONJON // ICAM','TEMPLE JAPONAIS','ARÈNE SPORTIVE','MANGA CITY','ATELIER D’ART'][(g.stage-1)%5],180,49,14,'#8ad5c8','center');for(let y=0;y<11;y++)for(let x=0;x<11;x++){const sx=ox+x*cell,sy=oy+y*cell,isWall=g.maze[y][x]==='#';round(c,sx,sy,cell-1,cell-1,3,isWall?'#315366':(x+y)%2?'#1c3544':'#233f4a');if(isWall){round(c,sx+3,sy+3,cell-8,7,2,'#597d84')}else{circle(c,sx+cell/2,sy+cell/2,2,'#416970')}const d=doorsMap[x+','+y];if(d!==undefined&&!g.doors[d]&&d<Math.min(5,2+g.stage)){round(c,sx+2,sy+3,cell-5,cell-5,4,'#a78348','#f7d6a2');label(c,'?',sx+cell/2,sy+20,17,'#fff3d6','center')}}const px=ox+(g.gx+.5)*cell,py=oy+(g.gy+.5)*cell;player(c,px,py,'#75d5b9',.75);circle(c,ox+9.5*cell,oy+9.5*cell,8,'#b6e792');label(c,'SORTIE',180,453,13,'#91d8c0','center');if(g.puzzle){round(c,20,184,320,165,17,'#0e2637','#a9cfc9');label(c,'PORTE VERROUILLÉE',180,214,13,'#f1d69c','center');label(c,g.puzzle.q,180,250,12,'#f1f3f0','center');label(c,'Choisis la réponse ci-dessous',180,290,12,'#a8c8ce','center')}}
function getMove(g){const move=g.move||{x:0,y:0};let x=move.x,y=move.y;if(activeKeys.has('ArrowLeft')||activeKeys.has('a'))x=-1;if(activeKeys.has('ArrowRight')||activeKeys.has('d'))x=1;if(activeKeys.has('ArrowUp')||activeKeys.has('w'))y=-1;if(activeKeys.has('ArrowDown')||activeKeys.has('s'))y=1;const len=Math.hypot(x,y)||1;return {x:x/len,y:y/len}}
function cyberMove(dx,dy){const g=game;if(!g||g.id!=='cyber'||g.puzzle||g.over)return;const x=g.gx+dx,y=g.gy+dy;if(x<0||x>=11||y<0||y>=11||g.maze[y][x]==='#')return;const d=doorsMap[x+','+y];if(d!==undefined&&!g.doors[d]&&d<Math.min(5,2+g.stage)){g.puzzle={...levelPuzzles(g.stage)[d],id:d};updateCyberUI();return}g.gx=x;g.gy=y;if(g.gx===9&&g.gy===9){if(g.solved<Math.min(5,2+g.stage)){toast('Ouvre toutes les portes du niveau !');return}inc(60*g.stage);S.progress.cyberStage=Math.max(S.progress.cyberStage||0,g.stage);persist();finishGame('cyber',g.solved,'Niveau '+g.stage+' terminé !')}}
function cyberLevels(){const max=Math.min(5,(S.progress?.cyberStage||0)+1);openModal('Cyber Lab · niveaux',`<p class="dim">Termine un niveau pour débloquer le suivant.</p><div class="grid2">${['Donjon de l’ICAM','Temple japonais','Stade scientifique','Manga City','Atelier créatif'].map((name,i)=>`<button class="tile" data-action="cyber-stage-${i+1}" ${i+1>max?'disabled':''}><strong>${i+1<=max?'🔓':'🔒'} Niveau ${i+1}</strong><span class="dim small">${name}</span></button>`).join('')}</div>`)}
function solveCyber(answer){const g=game;if(!g||g.id!=='cyber'||!g.puzzle)return;if(answer===g.puzzle.ok){const d=g.puzzle.id;g.doors[d]=true;g.solved++;inc(15);toast('Porte ouverte · +15 €');g.puzzle=null;updateCyberUI()}else{toast('Mauvaise réponse : réessaie');g.tries++}}
function updateCyberUI(){if(!game||game.id!=='cyber')return;const p=game.puzzle;$('#game-extra').innerHTML=p?`<div class="panel"><h3>${p.q}</h3><div class="grid3" style="margin-top:11px">${p.a.map((a,i)=>`<button class="btn alt sm" data-action="solve-cyber" data-answer="${i}">${a}</button>`).join('')}</div></div>`:''}
function drawAdventurer(c,x,y){circle(c,x,y+17,15,'#091b2388');round(c,x-12,y-15,24,32,5,'#6287a2','#d8b78b');poly(c,[[x-13,y-12],[x,y+2],[x+13,y-12],[x+9,y+7],[x-9,y+7]],'#28536b','#e4d2af');round(c,x-10,y+6,8,14,2,'#273f58');round(c,x+2,y+6,8,14,2,'#273f58');circle(c,x,y-27,12,'#d6aa83');poly(c,[[x-13,y-29],[x-7,y-42],[x+7,y-42],[x+15,y-31],[x+8,y-36],[x-3,y-32],[x-12,y-25]],'#3c3035');round(c,x+10,y-12,4,32,2,'#d4dce1');poly(c,[[x+12,y-33],[x+18,y-16],[x+9,y-14]],'#e3d6c1','#f3e6d1')}
function drawMob(c,z){const elite=z.kind==='elite',x=z.x,y=z.y;circle(c,x,y+11,16,'#0d1e2799');if(elite){poly(c,[[x-14,y+10],[x-17,y-11],[x-7,y-22],[x,y-14],[x+9,y-24],[x+17,y-11],[x+13,y+12]],'#a17e4e','#e2c69b');circle(c,x-5,y-5,2,'#fff');circle(c,x+5,y-5,2,'#fff')}else{poly(c,[[x-14,y+10],[x-17,y-5],[x-8,y-15],[x+1,y-19],[x+12,y-9],[x+15,y+12]],'#7d678f','#c59fbb');poly(c,[[x-6,y-15],[x-4,y-25],[x+2,y-17]],'#ae85a3');circle(c,x-5,y-2,2,'#ebf4dc');circle(c,x+5,y-2,2,'#ebf4dc')}round(c,x-13,y-28,26,4,2,'#402b35');round(c,x-13,y-28,26*Math.max(0,z.hp/z.max),4,2,'#87e6a7')}
function drawDungeon(c){const g=game;const pal=[['#27364b','#172836'],['#28483f','#142c2c'],['#594054','#281f36'],['#6e5143','#2f2d33']][g.zone];bkg(c,pal[0],pal[1]);for(let x=0;x<360;x+=40)for(let y=0;y<500;y+=40){round(c,x+1,y+1,38,38,2,((x+y)%80===0)?'#49616b':'#314652');c.strokeStyle='#3f5563';c.strokeRect(x,y,40,40)}for(let i=0;i<9;i++){const x=((i*73)%360),y=((i*111)%450);circle(c,x,y,4,'#7bc4b244')}for(const z of g.enemies)drawMob(c,z);drawAdventurer(c,g.px,g.py);const metal=['#8daaba','#b4c4ca','#e3c879','#8ad6e7','#be9dea'][Math.min(4,Math.floor(g.armor/2))];round(c,g.px-13,g.py-4,26,23,7,metal,'#efdbb3');round(c,g.px-11,g.py-35,22,10,4,'#283144');c.save();c.translate(g.px+13,g.py-15);c.rotate(-.55+Math.sin(g.time*4)*.13);const blade=['#c7d5dc','#d7ddd6','#f1d780','#8fdef5','#c0a5ff'][Math.min(4,Math.floor(g.weapon/2))];poly(c,[[0,0],[5,-36-g.weapon*2],[10,0]],blade,'#f9f1dd');round(c,-5,0,19,5,2,'#9c7a4d');c.restore();if(g.slash>0){c.beginPath();c.arc(g.px,g.py,45+g.weapon*7,Math.PI*1.25,Math.PI*1.95);c.strokeStyle='#f6d58f';c.lineWidth=6;c.stroke()}round(c,14,15,165,13,5,'#402f3c');round(c,14,15,165*clamp(g.hp/g.maxHp,0,1),13,5,'#86d9a7');label(c,'PV '+Math.ceil(g.hp)+' / '+g.maxHp,25,25,10,'#1c2d30');label(c,'NIV '+g.lv+' · '+g.kills+'/'+g.questKill,347,27,11,'#f6e5c9','right');label(c,['CRYPTES','FORÊT','CATACOMBES','FORTERESSE'][g.zone],180,54,12,'#f8dca8','center')}
function updateDungeonUI(){if(!game||game.id!=='dungeon')return;const g=game;$('#game-extra').innerHTML=`<div class="panel"><div class="row"><div><strong>⚔ Quête : libérer la zone ${g.zone+1}</strong><div class="dim small">Vaincs ${g.questKill} ennemis · ${g.kills} éliminés</div></div>${pill('LV '+g.lv,'gold')}</div><div class="progress" style="margin:10px 0"><i style="width:${Math.min(100,g.kills/g.questKill*100)}%"></i></div><div class="grid3">${boxstat('Épée','Niv. '+g.weapon)}${boxstat('Armure','Niv. '+g.armor)}${boxstat('Cristaux',g.materials)}</div><div class="grid2" style="margin-top:9px">${button('⚔ Forge : 5 cristaux','forge-weapon','btn alt sm',g.materials<5)}${button('🛡 Armure : 7 cristaux','forge-armor','btn alt sm',g.materials<7)}${button('♥ Potion ('+g.potions+')','dungeon-heal','btn alt sm',g.potions<=0)}${button('🎒 Inventaire','dungeon-bag','btn alt sm')}</div></div>`}
function upgradeDungeon(type='weapon'){const g=game;if(!g||g.id!=='dungeon')return;const cost=type==='armor'?7:5;if(g.materials<cost){toast('Il manque des cristaux');return}g.materials-=cost;g[type]++;S.dungeonSave={level:g.lv,xp:g.xp,weapon:g.weapon,armor:g.armor,materials:g.materials,quest:g.zone};persist();updateDungeonUI();toast(type==='armor'?'Armure renforcée !':'Nouvelle lame forgée !')}
function drawRunner(c){const g=game;bkg(c,'#7199b1','#c0b2ac');circle(c,282,86,32,'#f3ce9a');poly(c,[[0,230],[70,155],[150,209],[229,145],[360,201],[360,500],[0,500]],'#496a80');for(let i=0;i<8;i++){const x=((i*75-g.dist*1.4)%465+465)%465-40;round(c,x,255-(i%3)*35,45,250,2,'#31465b');for(let v=0;v<4;v++)for(let w=0;w<2;w++)round(c,x+10+w*20,267-(i%3)*35+v*40,8,13,1,'#e3d0a088')}round(c,0,413,360,87,0,'#344450');round(c,0,412,360,9,0,'#aab9ba');for(let i=0;i<8;i++)round(c,((i*75-g.dist*8)%465+465)%465,442,32,4,2,'#dfd39f');g.obstacles.forEach(z=>{if(z.type===1)poly(c,[[z.x,414],[z.x+z.w/2,414-z.h],[z.x+z.w,414]],'#b45f78','#ffe0d6');else if(z.type===2){circle(c,z.x+z.w/2,414-z.h/2,18,'#d47278','#f7c4d3');round(c,z.x,414-z.h/2-3,z.w,6,2,'#e7b8b2')}else if(z.type===3){round(c,z.x,414-z.h,z.w,z.h,8,'#5cb6a3','#a8f1c9');label(c,'↟',z.x+z.w/2,414-z.h/2+6,20,'#fff','center')}else if(z.type===4){circle(c,z.x+z.w/2,414-z.h,11,'#f3c970','#fff5b8');label(c,'★',z.x+z.w/2,414-z.h+5,12,'#7a5328','center')}else round(c,z.x,414-z.h,z.w,z.h,4,'#b68763','#e6baa2');if(z.type===0)round(c,z.x,414-z.h,z.w,8,2,'#e5c695')});player(c,g.x,g.y,'#82c7c2',1.2);label(c,Math.floor(g.dist)+' m',180,45,20,'#fff1d3','center')}
function jump(){const g=game;if(g&&g.id==='runner'&&!g.over&&Math.abs(g.vy)<3)g.vy=-430}
function makeResources(){return Array.from({length:32},(_,i)=>({x:rand(37,330),y:rand(115,445),kind:['tree','rock','food','ore','tree','rock','fiber'][i%7],used:false}))}
function drawSurvival(c){const g=game;bkg(c,'#6baab7','#78b7b5');poly(c,[[10,125],[165,67],[347,130],[346,443],[170,491],[11,437]],'#d9cf96','#f4e4aa');poly(c,[[30,135],[171,86],[327,145],[328,422],[167,471],[31,418]],'#669b6a','#8ebc77');for(let x=48;x<340;x+=38)for(let y=135;y<443;y+=38){c.fillStyle='#93ad7477';c.fillRect(x+(y%3)*2,y,2,3)}g.resources.forEach(z=>{if(z.used)return;if(z.kind==='tree'){round(c,z.x-4,z.y-5,8,23,2,'#6c5640');circle(c,z.x,z.y-13,16,'#396f50');circle(c,z.x+5,z.y-19,11,'#538d5c')}else if(z.kind==='rock'){poly(c,[[z.x-14,z.y+8],[z.x-9,z.y-6],[z.x+7,z.y-11],[z.x+14,z.y+8]],'#87999b','#cad2c7')}else if(z.kind==='ore'){poly(c,[[z.x-12,z.y+8],[z.x-7,z.y-9],[z.x+9,z.y-7],[z.x+14,z.y+8]],'#82b4d0','#d8f3f7')}else if(z.kind==='fiber'){circle(c,z.x,z.y,9,'#d8cc7f');label(c,'✦',z.x,z.y+4,12,'#62806b','center')}else{circle(c,z.x,z.y,9,'#c88c62');circle(c,z.x-2,z.y-2,4,'#f5dca1')}});if(g.shelter){round(c,238,344,57,52,6,'#8b6e4d');poly(c,[[226,349],[267,313],[310,349]],'#b9a07d');round(c,257,362,18,32,2,'#4d4038')}if(g.tool){label(c,'🪓',75,360,22,'#fff','center')}if(g.bench){round(c,277,329,44,16,3,'#997047');round(c,284,344,7,19,2,'#684a30');round(c,308,344,7,19,2,'#684a30')}if(g.forge){round(c,42,324,46,27,5,'#76828b');circle(c,75,320,9,'#eeb36a')}if(g.fire){poly(c,[[90,363],[110,355],[121,364],[103,373]],'#64483d');circle(c,105,352,12,'#e3aa57');circle(c,105,351,6,'#f4d89a')}player(c,g.px,g.py,'#d9b578',1);label(c,'Énergie '+Math.max(0,Math.ceil(g.energy))+' %',180,38,13,'#173e3e','center');round(c,70,46,220,10,6,'#2b5d5d');round(c,70,46,220*g.energy/100,10,6,'#f6df9a')}
function collectResource(){const g=game;if(!g||g.id!=='survival'||g.over)return;const obj=g.resources.filter(z=>!z.used&&Math.hypot(z.x-g.px,z.y-g.py)<45).sort((a,b)=>Math.hypot(a.x-g.px,a.y-g.py)-Math.hypot(b.x-g.px,b.y-g.py))[0];if(!obj){toast('Approche-toi d’une ressource !');return}obj.used=true;if(obj.kind==='tree')g.wood+=g.tool?2:1;if(obj.kind==='rock')g.stone+=g.tool?2:1;if(obj.kind==='ore')g.ore++;if(obj.kind==='fiber')g.rope++;if(obj.kind==='food'){g.food++;g.energy=Math.min(100,g.energy+16)}g.turns++;inc(2);updateSurvivalUI()}
function craftSurvival(type='fire'){const g=game;if(!g||g.id!=='survival')return;const recipes={fire:{wood:3,stone:2},tool:{wood:2,stone:3},bench:{wood:6,stone:4},shelter:{wood:8,rope:3},forge:{stone:8,ore:4},boat:{wood:14,rope:6,ore:3}};if(['shelter','forge','boat'].includes(type)&&!g.bench){toast('Construis d’abord un établi !');return}const item=recipes[type];if(!item)return;for(const [k,v] of Object.entries(item))if(g[k]<v){toast('Ressources manquantes : '+k+' ×'+v);return}for(const [k,v] of Object.entries(item))g[k]-=v;if(type==='fire')g.fire++;if(type==='tool')g.tool++;if(type==='bench')g.bench++;if(type==='shelter')g.shelter++;if(type==='forge')g.forge=(g.forge||0)+1;if(type==='boat')g.boat=1;g.crafted++;g.energy=Math.min(100,g.energy+20);inc({fire:35,tool:55,bench:95,shelter:160,forge:330,boat:900}[type]);S.survivalSave={camp:g.fire};persist();updateSurvivalUI();toast('Fabrication réussie : '+type);if(type==='boat')finishGame('survival',g.crafted*50+g.turns,'Île explorée, bateau terminé !')}
function updateSurvivalUI(){if(!game||game.id!=='survival')return;const g=game;const rec=[['Feu de camp','fire','3 bois + 2 pierres'],['Hache améliorée','tool','2 bois + 3 pierres'],['Établi','bench','6 bois + 4 pierres'],['Abri forestier','shelter','8 bois + 3 fibres'],['Forge','forge','8 pierres + 4 minerais'],['Bateau de sortie','boat','14 bois + 6 fibres + 3 minerais']];$('#game-extra').innerHTML=`<div class="panel"><div class="row"><h3>Survie · Jour ${g.day}</h3>${pill('Énergie '+Math.ceil(g.energy)+'%')}</div><p class="dim small">Explore l'île, fabrique des outils, un abri, une forge puis un bateau. Les améliorations restent visibles sur la carte.</p><div class="grid3">${boxstat('Bois',g.wood)}${boxstat('Pierre',g.stone)}${boxstat('Minerai',g.ore)}${boxstat('Fibres',g.rope)}${boxstat('Nourriture',g.food)}${boxstat('Fabrications',g.crafted)}</div><div class="grid2" style="margin-top:10px">${rec.map(i=>`<button class="btn alt sm" data-action="craft-${i[1]}">${i[0]}<br><small>${i[2]}</small></button>`).join('')}</div></div>`}
function setupControls(){const g=game,controls=$('#game-controls');if(!g)return;if(g.id==='basket')controls.innerHTML='<span class="dim small">Glisse le ballon, vise l’arceau, dose ta puissance : les tirs ratés comptent.</span>';else if(g.id==='runner')controls.innerHTML='<button data-gctrl="jump" class="large-control">↑ SAUTER</button>';else if(g.id==='match')controls.innerHTML=`<div class="basket-controls"><button data-gctrl="left">◀</button><button data-gctrl="right">▶</button><button data-gctrl="jump">SAUT</button><button data-gctrl="shoot">TIR</button><button data-gctrl="dribble">DRIBBLE</button><button data-gctrl="power" class="special">⚡ POUVOIR</button></div>`;else controls.innerHTML=`<div class="dpad"><span></span><button data-gctrl="up">↑</button><span></span><button data-gctrl="left">←</button><button data-gctrl="down">↓</button><button data-gctrl="right">→</button></div>${g.id==='dungeon'?'<button data-gctrl="attack" class="special">⚔ ATTAQUE</button><button data-gctrl="potion">♥ SOIN</button>':''}${g.id==='survival'?'<button data-gctrl="collect">✦ RAMASSER</button>':''}` }
function runControl(k){if(!game||game.over)return;const g=game;if(k==='jump'){if(g.id==='runner')jump();else if(g.id==='match'&&g.onGround){g.vy=-390;g.onGround=false}return}if(k==='shoot'){matchShoot();return}if(k==='dribble'&&g.id==='match'){g.dribble=1.8;g.px=clamp(g.px+g.look*28,23,337);toast('Dribble !');return}if(k==='power'&&g.id==='match'){if(!g.power){toast('Récupère le jeton au milieu !');return}g.power=0;if(g.hero===0){g.freeze=4;toast('❄ GEL ADVERSAIRE')}else if(g.hero===1){g.dunk={t:0,start:g.px};g.owner='player';toast('⚡ THUNDER DUNK !')}else{g.defend=5;toast('❄ PANIER PROTÉGÉ 5 S')}return}if(k==='potion'&&g.id==='dungeon'){if(g.potions>0){g.potions--;g.hp=Math.min(g.maxHp,g.hp+45);toast('Potion utilisée')}return}if(k==='attack'&&g.id==='dungeon'){g.attack=0;g.slash=.25;return}if(k==='collect'){collectResource();return}const dx=k==='left'?-1:k==='right'?1:0,dy=k==='up'?-1:k==='down'?1:0;if(g.id==='cyber')cyberMove(dx,dy);else g.move={x:dx,y:dy}}
function matchShoot(){const g=game;if(!g||g.id!=='match'||g.over||g.cooldown>0||g.owner!=='player'||g.ball)return;g.shots++;g.cooldown=.75;const dist=340-g.px,ideal=Math.max(.35,Math.min(.91,1.08-dist/550));const hit=Math.random()<ideal;g.ball={t:0,sx:g.px,sy:g.py-17,tx:332,ty:190,goal:hit,who:'player'};g.owner='shot';toast(hit?'Beau tir !':'Tir difficile…')}
document.addEventListener('pointerdown',ev=>{const b=ev.target.closest('[data-gctrl]');if(!b)return;ev.preventDefault();runControl(b.dataset.gctrl);b.setPointerCapture?.(ev.pointerId)});
document.addEventListener('pointerup',ev=>{const b=ev.target.closest('[data-gctrl]');if(!b||!game)return;const key=b.dataset.gctrl;if(['left','right','up','down'].includes(key))game.move=null});
document.addEventListener('pointercancel',()=>{if(game)game.move=null});
document.addEventListener('click',ev=>{if(ev.target.closest('[data-action="surv-collect"]'))collectResource()});
function posPointer(ev){const r=game.canvas.getBoundingClientRect();return{x:(ev.clientX-r.left)/r.width*360,y:(ev.clientY-r.top)/r.height*500}}
function gamePointerDown(ev){if(!game||game.over)return;const p=posPointer(ev);if(game.id==='basket'){game.pointer={...p,x2:p.x,y2:p.y};game.canvas.setPointerCapture(ev.pointerId)}else if(game.id==='runner')jump();else if(game.id==='match'){game.pointer=p}else if(game.id==='survival'){const dx=p.x-game.px,dy=p.y-game.py,dist=Math.hypot(dx,dy);if(dist<45)collectResource();else game.move={x:dx/dist,y:dy/dist}}else if(game.id==='dungeon'){const dx=p.x-game.px,dy=p.y-game.py,dist=Math.hypot(dx,dy)||1;game.move={x:dx/dist,y:dy/dist}}else if(game.id==='cyber'){const dx=p.x-(18+(game.gx+.5)*29.5),dy=p.y-(89+(game.gy+.5)*29.5);cyberMove(Math.abs(dx)>Math.abs(dy)?Math.sign(dx):0,Math.abs(dx)>Math.abs(dy)?0:Math.sign(dy))}}
function gamePointerMove(ev){if(!game)return;const p=posPointer(ev);if(game.id==='basket'&&game.pointer){game.pointer.x2=p.x;game.pointer.y2=p.y}else if(['dungeon','survival'].includes(game.id)&&game.move){const dx=p.x-game.px,dy=p.y-game.py,len=Math.hypot(dx,dy)||1;game.move={x:dx/len,y:dy/len}}}
function gamePointerUp(ev){if(!game)return;if(game.id==='basket'&&game.pointer&&!game.ball){const p=posPointer(ev),start=game.pointer,dy=Math.max(20,start.y-p.y),dx=p.x-start.x;game.ball={t:0,targetX:180+dx*.86+rand(-4,4),power:clamp(dy/255,.08,1.38)};game.pointer=null}else if(game.id==='match'&&game.pointer){const p=posPointer(ev);if(Math.hypot(p.x-game.pointer.x,p.y-game.pointer.y)<25)matchShoot();game.pointer=null}else if(game.move)game.move=null}
document.addEventListener('keydown',ev=>{if(!game)return;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight',' '].includes(ev.key))ev.preventDefault();activeKeys.add(ev.key);if(game.id==='runner'&&(ev.key===' '||ev.key==='ArrowUp'))jump();else if(game.id==='match'&&ev.key===' ')matchShoot();else if(game.id==='survival'&&ev.key===' ')collectResource();else if(game.id==='cyber'){const d={ArrowUp:[0,-1],ArrowDown:[0,1],ArrowLeft:[-1,0],ArrowRight:[1,0]}[ev.key];if(d&&!ev.repeat)cyberMove(...d)}});
document.addEventListener('keyup',ev=>activeKeys.delete(ev.key));
header();render();
